/** A stable fake SHA for a commit key (as the generated seed derives them). */
const sha = (seed: string) => {
  let hash = 2166136261;
  let out = "";
  for (let round = 0; out.length < 40; round++) {
    for (const char of `${seed}:${round}`) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619);
    out += (hash >>> 0).toString(16).padStart(8, "0");
  }
  return out.slice(0, 40);
};

type SeedCommit = {
  readonly sha: string;
  readonly message: string;
  readonly author: { readonly login: string; readonly name: string };
  readonly committedAt: string;
};

const commit = (
  key: string,
  message: string,
  author: keyof typeof people,
  committedAt: string,
): SeedCommit => ({ sha: sha(key), message, author: people[author], committedAt });

