// ---------------------------------------------------------------- reading the generated seed

/** A results part, as `RecordResults` stores it. */
type Part = "tests" | "cases" | "traces";

/**
 * What the offline reporter (`@highalch/console-client` without a URL) wrote for one run, in
 * `<dir>/runs/<id>/`: its artifacts (`artifacts.json`, bodies in `artifacts/<sha256>.<ext>`) and
 * its results objects (`results/<n>.<part>.json`, each an array of the part's items).
 */
type Offline = {
  readonly artifacts: ReadonlyArray<{
    readonly name: string;
    readonly mime: string;
    /** The reporter's local id (`local-<sha256>`), which its results name. */
    readonly id: string;
    readonly body: Uint8Array;
  }>;
  /** Results objects as JSON text (artifact ids still the reporter's local ones). */
  readonly results: ReadonlyArray<{ readonly part: Part; readonly text: string }>;
};

const newestRunDir = Effect.fn("seed.newestRunDir")(function* (root: string) {
  const dir = join(root, "runs");
  const names = yield* Effect.promise(() => readdir(dir));
  const times = yield* Effect.forEach(names, (name) =>
    Effect.promise(() => stat(join(dir, name)).then((info) => info.mtimeMs)),
  );
  const newest = names
    .map((name, position) => ({ name, time: times[position] ?? 0 }))
    .sort((a, b) => a.time - b.time)
    .at(-1)?.name;
  if (newest === undefined)
    return yield* Effect.die(`No run in ${dir}; run \`vp run @highalch/console-web#seed\``);
  return join(dir, newest);
});

/** The part a results object holds, from its name (`<n>.<part>.json`). */
const partOf = (file: string) => {
  const part = file.split(".").at(-2);
  return part === "tests" || part === "cases" || part === "traces"
    ? Effect.succeed<Part>(part)
    : Effect.die(`Not a results object: ${file}`);
};

const readOffline = Effect.fn("seed.readOffline")(function* (seedRoot: string, run: SeedRun) {
  if (run.source.kind === "stories") return { artifacts: [], results: [] } satisfies Offline;
  const dir = yield* newestRunDir(
    run.source.kind === "playwright"
      ? join(seedRoot, "playwright", `step-${run.source.step}`)
      : join(seedRoot, "fuzz", run.source.name),
  );
  // A run without artifacts has no `artifacts.json` (nor an `artifacts` folder).
  const declared = JSON.parse(
    yield* Effect.promise(() => readFile(join(dir, "artifacts.json"), "utf8").catch(() => "[]")),
  ) as ReadonlyArray<{
    readonly name: string;
    readonly mime: string;
    readonly sha256: string;
    readonly id: string;
  }>;
  const stored = yield* Effect.promise(() => readdir(join(dir, "artifacts")).catch(() => []));
  const artifacts = yield* Effect.forEach(declared, (entry) => {
    const file = stored.find((name) => name.startsWith(`${entry.sha256}.`));
    if (file === undefined) return Effect.die(`No body for artifact ${entry.sha256} in ${dir}`);
    return Effect.map(
      Effect.promise(() => readFile(join(dir, "artifacts", file))),
      (body) => ({ name: entry.name, mime: entry.mime, id: entry.id, body: new Uint8Array(body) }),
    );
  });
  const files = (yield* Effect.promise(() => readdir(join(dir, "results")))).sort();
  const results = yield* Effect.forEach(files, (file) =>
    Effect.all({
      part: partOf(file),
      text: Effect.promise(() => readFile(join(dir, "results", file), "utf8")),
    }),
  );
  return { artifacts, results } satisfies Offline;
});

// ---------------------------------------------------------------- results as stored parts

type Json = unknown;

/** Splits items into objects of at most ~900 KB (CI's limit is 1 MB per part). */
const chunks = (items: ReadonlyArray<Json>) => {
  const out: Array<Array<Json>> = [];
  let current: Array<Json> = [];
  let size = 2;
  for (const item of items) {
    const bytes = JSON.stringify(item).length + 1;
    if (current.length > 0 && size + bytes > 900_000) {
      out.push(current);
      current = [];
      size = 2;
    }
    current.push(item);
    size += bytes;
  }
  if (current.length > 0) out.push(current);
  return out;
};

const encoder = new TextEncoder();
const sha256 = (body: Uint8Array) => createHash("sha256").update(body).digest("hex");

const counts = (parts: Record<Part, ReadonlyArray<Json>>) => {
  const tests = { passed: 0, failed: 0, flaky: 0, skipped: 0 };
  for (const test of parts.tests) {
    const status = (test as { readonly status: keyof typeof tests }).status;
    tests[status] += 1;
  }
  const cases = { ok: 0, overflow: 0, crash: 0, a11y: 0 };
  for (const item of parts.cases) {
    const outcome = (item as { readonly case: { readonly outcome: string } }).case.outcome;
    if (outcome in cases) cases[outcome as keyof typeof cases] += 1;
  }
  const traces = { passed: 0, failed: 0 };
  for (const trace of parts.traces)
    traces[(trace as { readonly failure: Json }).failure === null ? "passed" : "failed"] += 1;
  return { tests, cases, traces };
};

// ---------------------------------------------------------------- sending

const system = { _tag: "System", name: "dev-seed" } as const;

/** Seeds the hosted Console. `seedRoot` is the app's generated `.seed` folder (`dev/runs/`). */
export const seed = (seedRoot: string) => (clock: SeedClock, idle: Effect.Effect<void>) =>
  Effect.gen(function* () {
    const organizations = yield* Organization;
    const projects = yield* Project;
    const repositories = yield* Repository;
    const objects = yield* Objects;
    const runAggregate = yield* Run;
    // Policies (RunIntake, comparison) apply CI's writes to the run in the background, stamped
    // with the clock when they run: wait until the run shows a write before moving the clock.
    const until = (run: RunId, applied: (state: RunState) => boolean) =>
      runAggregate.get(run).pipe(
        Effect.flatMap((state) => (applied(state) ? Effect.void : Effect.fail("pending" as const))),
        Effect.retry({ schedule: Schedule.spaced("2 millis"), times: 5_000 }),
        Effect.orDie,
      );
    // Policies (RunIntake, comparison) run in the background: let them finish at this time
    // before the clock moves on.
    const at = (iso: string, minutes = 0) =>
      Effect.andThen(
        // Deliveries start on a later tick: give them one, then wait until nothing runs.
        Effect.andThen(Effect.sleep("2 millis"), idle),
        Effect.sync(() => {
          clock.at = Date.parse(iso) + minutes * MINUTE;
        }),
      );

    // Organisations on a current paid period, both owned by the development user.
    for (const [org, name, created] of [
      [acme, "Acme", "2026-10-01T09:00:00.000Z"],
      [initech, "Initech", "2026-09-01T09:00:00.000Z"],
    ] as const) {
      yield* at(created);
      yield* organizations.send(
        org,
        new CreateOrganization({
          org,
          name,
          owner: developer.id,
          ownerEmail: developer.email,
          ownerName: developer.name,
        }),
      );
      const start = Date.parse("2026-11-01T00:00:00.000Z");
      yield* organizations.send(
        org,
        new ActivatePlan({ plan: "team", periodStart: start, periodEnd: start + 30 * DAY }),
      );
    }

    for (const project of [
      { slug: "crm", org: acme, repository: "acme/crm", created: "2026-10-01T09:30:00.000Z" },
      {
        slug: "notes-app",
        org: acme,
        repository: "acme/notes-app",
        // The oldest project: an organisation opens on its oldest project's stories.
        created: "2026-10-01T09:15:00.000Z",
      },
      { slug: "billing-portal", org: acme, repository: null, created: "2026-10-20T09:00:00.000Z" },
      {
        slug: "tps-reports",
        org: initech,
        repository: "initech/tps",
        created: "2026-09-02T09:00:00.000Z",
      },
    ] as const) {
      yield* at(project.created);
      const slug = ProjectId.make(project.slug);
      const repository = project.repository === null ? null : RepositoryId.make(project.repository);
      yield* projects.send(
        slug,
        new CreateProject({ slug, org: project.org, repository, defaultBranch: "main" }),
      );
      if (repository !== null)
        yield* repositories.send(
          repository,
          new ClaimRepository({ repository, project: slug, org: project.org }),
        );
    }

    // The runs, in commit order.
    for (const [position, run] of runs.entries()) {
      const offline = yield* readOffline(seedRoot, run);
      const id = RunId.make(run.id);
      const kind = run.source.kind;
      const project = ProjectId.make(run.project ?? "crm");
      const pull = run.pr === undefined ? null : pulls[run.pr];
      yield* at(run.commit.committedAt, 3 + position);
      yield* organizations.send(
        acme,
        new OpenRun({
          org: acme,
          run: id,
          project,
          commit: run.commit.sha,
          branch: run.branch,
          pr: run.pr ?? null,
          source: run.source.kind === "stories" ? "vp test" : "github-actions",
          kind,
          baseBranch: pull?.base ?? run.branch,
          commitInfo: {
            message: run.commit.message,
            author: run.commit.author,
            committedAt: run.commit.committedAt,
          },
          pull,
        }),
      );
      yield* until(id, (state) => state._tag === "Run");

      // Artifacts: bodies stored first (as CI PUTs them), declared in batches of 100.
      const ids = new Map<string, string>();
      // What the run should hold before it completes (CI's writes reach it through RunIntake).
      let artifactsSent = 0;
      let rowsSent = 0;
      const rowsOf = (state: RunState) =>
        state._tag !== "Run"
          ? 0
          : Object.values(state.summary.tests).reduce((n, v) => n + v, 0) +
            Object.values(state.summary.cases).reduce((n, v) => n + v, 0) +
            Object.values(state.summary.traces).reduce((n, v) => n + v, 0);
      const stories = run.source.kind === "stories" ? storiesOf(run.id, run.source.moment) : [];
      const storyFiles = stories.flatMap((story) => story.files);
      const all = [
        ...offline.artifacts.map((a) => ({
          local: a.id,
          name: a.name,
          mime: a.mime,
          body: a.body,
        })),
        ...storyFiles.map((f) => ({ local: f.local, name: f.name, mime: f.mime, body: f.body })),
      ];
      for (let from = 0; from < all.length; from += 100) {
        const batch = all.slice(from, from + 100);
        for (const artifact of batch)
          objects.set(objectKey(acme, sha256(artifact.body), 0), {
            body: artifact.body,
            mime: artifact.mime,
          });
        const receipt = yield* organizations.send(
          acme,
          new DeclareArtifacts({
            org: acme,
            run: id,
            artifacts: batch.map((artifact) => ({
              name: artifact.name,
              mime: artifact.mime,
              bytes: artifact.body.byteLength,
              sha256: sha256(artifact.body),
            })),
          }),
        );
        batch.forEach((artifact, index) => {
          const accepted = receipt.reply.ids[index];
          if (accepted !== undefined) ids.set(artifact.local, accepted);
        });
        artifactsSent += batch.length;
        const expected = artifactsSent;
        yield* until(id, (state) => state._tag === "Run" && state.summary.artifacts >= expected);
      }

      // Results: each object's parts stored at the keys the reply names, at most 3 per command.
      for (const { part, text } of offline.results) {
        let mapped = text;
        for (const [local, accepted] of ids)
          mapped = mapped.replaceAll(`"${local}"`, `"${accepted}"`);
        const objectsOfBatch = chunks(JSON.parse(mapped) as ReadonlyArray<Json>).map((chunk) => ({
          part,
          chunk,
          body: encoder.encode(JSON.stringify(chunk)),
        }));
        for (let from = 0; from < objectsOfBatch.length; from += 3) {
          const group = objectsOfBatch.slice(from, from + 3);
          const counted = counts({
            tests: group.filter((g) => g.part === "tests").flatMap((g) => g.chunk),
            cases: group.filter((g) => g.part === "cases").flatMap((g) => g.chunk),
            traces: group.filter((g) => g.part === "traces").flatMap((g) => g.chunk),
          });
          const receipt = yield* organizations.send(
            acme,
            new RecordResults({
              org: acme,
              run: id,
              kind,
              parts: group.map((g) => ({
                part: g.part,
                sha256: sha256(g.body),
                bytes: g.body.byteLength,
                count: g.chunk.length,
              })),
              ...counted,
            }),
          );
          receipt.reply.keys.forEach((key, index) => {
            const stored = group[index];
            if (stored !== undefined)
              objects.set(key, { body: stored.body, mime: "application/json" });
          });
          rowsSent += group.reduce((n, g) => n + g.chunk.length, 0);
          const expected = rowsSent;
          yield* until(id, (state) => rowsOf(state) >= expected);
        }
      }

      for (const story of stories) yield* recordStory(organizations, id, story, ids);
      // Stories leave no trace on the run's state: let RunIntake pass them before completing.
      if (stories.length > 0) yield* Effect.andThen(Effect.sleep("5 millis"), idle);

      yield* at(run.commit.committedAt, 3 + position + (kind === "playwright" ? 4 : 2));
      yield* organizations.send(acme, new CompleteRun({ org: acme, run: id }));
      yield* until(
        id,
        (state) => state._tag === "Run" && state.status === "completed" && state.compared,
      );
    }
    // The last run's completion (RunIntake → FinishRun) still runs at its own time.
    yield* Effect.andThen(Effect.sleep("2 millis"), idle);
    yield* Effect.andThen(Effect.sleep("2 millis"), idle);
  }).pipe(Effect.provideService(CurrentActor, system));

const recordStory = (
  organizations: (typeof Organization)["Service"],
  run: RunId,
  story: SeedStory,
  ids: ReadonlyMap<string, string>,
) => {
  const idOf = (local: string) => ids.get(local) ?? local;
  return organizations.send(
    acme,
    new RecordStory({
      org: acme,
      run,
      story: { ...story.header, report: idOf(story.header.report) },
      summary: story.summary,
      frames: story.frames.map(idOf),
    }),
  );
};
